// A tela de carregamento sai assim que o HTML está pronto (antes esperava imagens, widget e pixel + 1,4 s).
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => document.getElementById('loading').classList.add('hidden'), 150);
});

.reveal-right.visible { opacity: 1; transform: translateX(0); }
/* No celular o deslocamento lateral criava rolagem para o lado; entra de baixo para cima. */
@media (max-width: 768px) { .reveal-left, .reveal-right { transform: translateY(20px); } }
